def wildcard_dictionary(ops):
    root = {}
    out = []
    def find(node, pat, i):
        if i == len(pat):
            return '$' in node
        c = pat[i]
        if c == '.':
            return any(find(child, pat, i + 1) for k, child in node.items() if k != '$')
        return c in node and find(node[c], pat, i + 1)
    for op in ops:
        if op[0] == 'add':
            node = root
            for c in op[1]:
                node = node.setdefault(c, {})
            node['$'] = True
        else:
            out.append(find(root, op[1], 0))
    return out
